  "Glide": { sole: "PVC", mrp_start: 699, mrp_end: 999, image: "data:image/jpeg;base64," },
  "Grace": { sole: "PVC", mrp_start: 699, mrp_end: 999, image: "data:image/jpeg;base64," },
  "Jack/Jill": { sole: "EVA", mrp_start: 749, mrp_end: 999, image: "data:image/jpeg;base64," },
