  "Symbol": { sole: "EVA", mrp_start: 749, mrp_end: 999, image: "data:image/jpeg;base64," },
  "Apex": { sole: "EVA", mrp_start: 769, mrp_end: 1099, image: "data:image/jpeg;base64," },
  "Aero": { sole: "EVA", mrp_start: 899, mrp_end: 1110, image: "data:image/jpeg;base64," },
